<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { BarChart3, CalendarRange, Download, FileSpreadsheet, FileText, RefreshCw } from 'lucide-vue-next';
import api, { apiError } from '../services/api';
import { formatColumn, timezoneFor } from '../utils/datetime';
import { useAuthStore } from '../stores/auth';
const auth = useAuthStore(); const timezone = computed(() => timezoneFor(auth.user));
const types = [{ key: 'expenses', label: 'Expenses' }, { key: 'budgets', label: 'Budgets' }, { key: 'maintenance', label: 'Maintenance' }, { key: 'assets', label: 'Assets' }, { key: 'vehicles', label: 'Vehicle expenses' }, { key: 'insurance', label: 'Insurance' }, { key: 'subscriptions', label: 'Subscriptions' }, { key: 'inventory', label: 'Inventory' }];
const type = ref('expenses'); const from = ref(''); const to = ref(''); const report = ref(null); const loading = ref(false); const error = ref('');
const load = async () => { loading.value = true; error.value = ''; try { report.value = (await api.get(`/reports/${type.value}`, { params: { from: from.value || undefined, to: to.value || undefined } })).data; } catch (e) { error.value = apiError(e); } finally { loading.value = false; } };
const download = async (format) => { try { const response = await api.get(`/reports/export/${type.value}/${format}`, { params: { from: from.value || undefined, to: to.value || undefined }, responseType: 'blob' }); const url = URL.createObjectURL(response.data); const a = document.createElement('a'); a.href = url; a.download = `${type.value}-report.${format === 'excel' ? 'xlsx' : 'pdf'}`; a.click(); URL.revokeObjectURL(url); } catch (e) { error.value = apiError(e); } };
watch(type, load); onMounted(load);
</script>
<template><div class="mx-auto max-w-[1400px] space-y-5 fade-up"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="eyebrow flex items-center gap-2"><BarChart3 :size="13" /> Intelligence layer</p><h1 class="mt-2 text-3xl font-semibold">Reports & exports</h1><p class="mt-1 text-sm text-[#86ada3]">Turn household activity into decisions you can act on.</p></div><div class="flex gap-2"><button class="btn-secondary" @click="download('excel')"><FileSpreadsheet :size="15" /> Excel</button><button class="btn-secondary" @click="download('pdf')"><FileText :size="15" /> PDF</button></div></div><section class="panel p-4"><div class="flex flex-col gap-3 md:flex-row md:items-end"><div class="flex-1"><label class="label">Report</label><select v-model="type" class="field"><option v-for="item in types" :key="item.key" :value="item.key">{{ item.label }}</option></select></div><div><label class="label">From</label><input v-model="from" type="date" class="field" @change="load"/></div><div><label class="label">To</label><input v-model="to" type="date" class="field" @change="load"/></div><button class="btn-primary" :disabled="loading" @click="load"><RefreshCw :size="15" :class="loading ? 'animate-spin' : ''" /> Run report</button></div></section><p v-if="error" class="rounded-xl bg-rose-400/10 px-4 py-3 text-sm text-rose-200">{{ error }}</p><div v-if="loading" class="panel p-10 text-center text-sm text-[#7da99c]">Preparing your report…</div><template v-else-if="report"><div class="grid gap-4 sm:grid-cols-3"><div class="panel p-5"><p class="eyebrow">Records</p><p class="mt-2 text-3xl font-semibold">{{ report.summary.count }}</p></div><div class="panel p-5"><p class="eyebrow">Total tracked</p><p class="mt-2 text-3xl font-semibold">{{ report.summary.total === null ? '—' : new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(report.summary.total) }}</p></div><div class="panel p-5"><p class="eyebrow">Date range</p><p class="mt-2 text-sm text-[#c5eadb]">{{ from || 'Beginning' }} → {{ to || 'Now' }}</p></div></div><section class="panel overflow-hidden"><div class="flex items-center gap-3 border-b border-emerald-100/10 px-5 py-4"><CalendarRange :size="17" class="text-emerald-200"/><h2 class="font-semibold">{{ types.find((item) => item.key === type)?.label }} detail</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[700px] text-left text-sm"><thead class="text-[10px] uppercase tracking-[.14em] text-[#679689]"><tr><th v-for="column in report.columns" :key="column" class="whitespace-nowrap px-5 py-3">{{ column.replaceAll('_', ' ') }}</th></tr></thead><tbody><tr v-for="row in report.data" :key="row.id" class="table-row"><td v-for="column in report.columns" :key="column" class="whitespace-nowrap px-5 py-3 text-[#c1e4d6]">{{ formatColumn(column, typeof row[column] === 'object' ? (row[column]?.name || row[column]?.title || row[column]) : row[column], timezone) }}</td></tr></tbody></table></div><div v-if="!report.data.length" class="p-10 text-center text-sm text-[#719b8e]">No records for this date range.</div></section></template></div></template>
